{
  "title": "The Rescue of the Ember Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A ruined skyline greets the rescuers at dawn.",
      "visual_description": "Wide shot of a broken royal city silhouetted against orange dawn light, crumbled spires and tattered banners. Three small figures stand on a ridge overlooking the ruins.",
      "characters": ["Captain Aelric", "Mira the Scout", "Brindle the Mage"]
    },
    {
      "scene_number": 2,
      "caption": "The map reveals the heir's prison tower.",
      "visual_description": "Close on weathered hands unrolling a glowing parchment map across a mossy stone, magical ink tracing routes through the ruined city.",
      "characters": ["Captain Aelric", "Brindle the Mage"]
    },
    {
      "scene_number": 3,
      "caption": "A scout slips ahead to read the gates.",
      "visual_description": "A cloaked figure crouches in tall weeds beside a colossal iron castle gate, watching armored patrols march past with torches.",
      "characters": ["Mira the Scout"]
    },
    {
      "scene_number": 4,
      "caption": "The party meets a frightened townsperson hiding in a cellar.",
      "visual_description": "A trembling old woman in patched shawls clutches a candle in a low brick cellar, the rescuers kneeling around her in warm candlelight.",
      "characters": ["Captain Aelric", "Brindle the Mage", "Old Henna"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon coil through the marketplace ruins.",
      "visual_description": "Cracked market square strewn with overturned carts and scorched stalls; a long claw-mark gouge runs across the cobbles. The scout traces it with one finger.",
      "characters": ["Mira the Scout", "Old Henna"]
    },
    {
      "scene_number": 6,
      "caption": "A sleepy gate official is bribed with honey cakes.",
      "visual_description": "A round, yawning official in a too-large helmet sits on a barrel at a side postern, accepting a cloth bundle of pastries with one half-open eye.",
      "characters": ["Captain Aelric", "Warden Bompo"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower looms at the city's heart.",
      "visual_description": "A tall blackened tower wrapped in slow-drifting purple mist, its windows glowing faint green. The party stands small at its base.",
      "characters": ["Captain Aelric", "Mira the Scout", "Brindle the Mage"]
    },
    {
      "scene_number": 8,
      "caption": "An armored patrol crosses the courtyard.",
      "visual_description": "Six knights in tarnished plate march in formation across a moonlit courtyard while the rescuers press flat against a fallen column.",
      "characters": ["Captain Aelric", "Mira the Scout", "Brindle the Mage"]
    },
    {
      "scene_number": 9,
      "caption": "A magic door bars the tower's entrance.",
      "visual_description": "An arched door of woven silver runes pulses with cold blue light. The mage raises both hands, fingers tracing matching sigils in the air.",
      "characters": ["Brindle the Mage"]
    },
    {
      "scene_number": 10,
      "caption": "Inside, old royal banners hang in ghostly silence.",
      "visual_description": "A long stone hall lined with moth-eaten crimson banners bearing a golden stag crest. Dust motes drift through shafts of pale light.",
      "characters": ["Captain Aelric", "Mira the Scout"]
    },
    {
      "scene_number": 11,
      "caption": "A spectral guardian challenges the intruders.",
      "visual_description": "A translucent armored figure forms from rising dust at the top of a spiral staircase, sword of pale fire drawn.",
      "characters": ["Captain Aelric", "The Pale Sentinel"]
    },
    {
      "scene_number": 12,
      "caption": "The mage unbinds the guardian's oath.",
      "visual_description": "Brindle holds up a small bone token; threads of silver light unspool from the spectral knight, who bows his head as he dissolves.",
      "characters": ["Brindle the Mage", "The Pale Sentinel"]
    },
    {
      "scene_number": 13,
      "caption": "The captive heir is found chained in a circle of runes.",
      "visual_description": "A young figure in tattered fine clothes kneels at the center of a glowing rune circle on the tower's top floor, wrists bound in chains of light.",
      "characters": ["Prince Cael", "Captain Aelric"]
    },
    {
      "scene_number": 14,
      "caption": "The scout disarms the rune lock.",
      "visual_description": "Mira kneels at the edge of the rune circle, prying a glowing crystal from the floor with a slender dagger; the chains of light begin to fray.",
      "characters": ["Mira the Scout", "Prince Cael"]
    },
    {
      "scene_number": 15,
      "caption": "A dragon's roar shakes the tower.",
      "visual_description": "View through a shattered tower window: an enormous red dragon banks past broken spires, wings blotting out the moon.",
      "characters": ["Captain Aelric", "Prince Cael", "Brindle the Mage"]
    },
    {
      "scene_number": 16,
      "caption": "They flee down the tower as patrols close in.",
      "visual_description": "The rescuers race down a crumbling spiral staircase, torches and shouting helmets visible far below through gaps in the stonework.",
      "characters": ["Captain Aelric", "Mira the Scout", "Brindle the Mage", "Prince Cael"]
    },
    {
      "scene_number": 17,
      "caption": "The mage conjures a path across the broken bridge.",
      "visual_description": "A vast stone bridge yawns in half over a misty chasm. Brindle's staff blazes white, and slabs of glowing light stitch the gap together.",
      "characters": ["Brindle the Mage", "Captain Aelric", "Mira the Scout", "Prince Cael"]
    },
    {
      "scene_number": 18,
      "caption": "They cross to freedom as the city burns behind them.",
      "visual_description": "Silhouetted figures hurry along the magical bridge at sunrise; behind them the ruined city glows orange under the circling dragon's fire.",
      "characters": ["Captain Aelric", "Mira the Scout", "Brindle the Mage", "Prince Cael"]
    }
  ]
}

